def quick_sort(lst):
    length = len(lst)

    # 如果列表长度小于等于1，直接返回
    if length <= 1:
        return lst
    else:
        # 选择一个基准元素
        pivot = lst.pop()

    # 创建两个列表，一个存储大于基准的元素，一个存储小于基准的元素
    elements_greater = []
    elements_smaller = []

    # 遍历列表，将元素分配到两个列表中
    for element in lst:
        if element > pivot:
            elements_greater.append(element)
        else:
            elements_smaller.append(element)

    # 对两个列表进行递归排序，并将结果合并
    return quick_sort(elements_smaller) + [pivot] + quick_sort(elements_greater)

# 接收整数输入并将其转换为列表
data_list = list(map(int, input().split()))

sorted_list = quick_sort(data_list)
print(sorted_list)
